<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/receivables.php';require_once dirname(__DIR__).'/private/ui.php';
$id=max(0,(int)($_GET['id']??0));$error='';$proposal=null;$state=null;$history=[];$list=[];$more=false;$page=max(1,min(10000,(int)($_GET['page']??1)));
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{if(($_POST['action']??'')==='preview'){$token=reminderSavePreview($pdo,(int)$_SESSION['admin_id'],$id,$_POST);redirect('receivables.php?id='.$id.'&proposal='.$token);}elseif(($_POST['action']??'')==='apply'){if(empty($_POST['confirm']))throw new RuntimeException('Erinnerung ausdrücklich bestätigen.');$reminder=reminderApply($pdo,(int)$_SESSION['admin_id'],(string)($_POST['token']??''));$_SESSION['app_notice']='Zahlungserinnerung #'.$reminder.' bestätigt und unverändert archiviert. Nicht versendet.';}else throw new RuntimeException('Aktion unbekannt.');}catch(Throwable $e){gszUiError($e);}redirect('receivables.php'.($id?'?id='.$id:''));}
try{if($id){$state=receivableState($pdo,$id);$q=$pdo->prepare('SELECT * FROM invoice_reminders WHERE invoice_id=? ORDER BY stage');$q->execute([$id]);$history=$q->fetchAll();if(isset($_GET['proposal'])){$q=$pdo->prepare('SELECT * FROM invoice_reminder_proposals WHERE token=? AND admin_id=? AND invoice_id=?');$q->execute([(string)$_GET['proposal'],$_SESSION['admin_id'],$id]);$proposal=$q->fetch();}}
$q=$pdo->query("SELECT i.id,i.number,i.recipient_name,i.gross_total,i.due_date,COALESCE(p.paid_cents,0) paid_cents FROM invoices i LEFT JOIN (SELECT invoice_id,SUM(amount_cents) paid_cents FROM finance_payments WHERE invoice_id IS NOT NULL GROUP BY invoice_id) p ON p.invoice_id=i.id WHERE i.document_kind='invoice' AND i.status='issued' ORDER BY i.due_date,i.id LIMIT 31 OFFSET ".(($page-1)*30));$list=$q->fetchAll();$more=count($list)>30;$list=array_slice($list,0,30);
}catch(Throwable $e){gszUiError($e);}gszPageStart('Offene Posten und Zahlungserinnerungen');
?><p>Offene Beträge berücksichtigen erfasste Teilzahlungen und Gegenzeilen. Keine automatische Gebühr, kein Zins und kein Versand. Erinnerungsstufe ist ein interner Ablauf, keine rechtliche Mahnprüfung.</p>
<section class="card"><h2>Offene Rechnungen</h2><?php foreach($list as $i):?><article class="task-row"><a href="?id=<?=(int)$i['id']?>"><?=e($i['number'].' · '.$i['recipient_name'])?></a><p>Fällig <?=e($i['due_date'])?> · Offen <?=e(financeDecimal(max(0,financeCents($i['gross_total'])-(int)$i['paid_cents'])))?> EUR</p></article><?php endforeach?><?php if(!$list):?><p>Keine offenen Rechnungen in dieser Ansicht.</p><?php endif?></section><nav><?php if($page>1):?><a href="?page=<?=$page-1?>">Zurück</a><?php endif?> <?php if($more):?><a href="?page=<?=$page+1?>">Weitere</a><?php endif?></nav>
<?php if($state):$i=$state['invoice'];?><section class="card"><h2><?=e($i['number'])?></h2><p>Offen <?=e(financeDecimal($state['outstanding_cents']))?> EUR · <a href="invoice.php?id=<?=$id?>">Rechnung</a> · <a href="accounting.php?invoice=<?=$id?>">Zahlung erfassen</a></p>
<?php if($proposal):$data=json_decode($proposal['payload'],true);?><h3>Vorschau – noch nicht bestätigt</h3><p>Stufe <?=(int)$data['stage']?> · <?=e($data['issued_on'])?> · Zahlungsziel <?=e($data['due_on'])?> · <?=e(financeDecimal((int)$data['outstanding_cents']))?> EUR</p><p style="white-space:pre-wrap"><?=e($data['body'])?></p><form method="post"><?php gszFields('apply');?><input type="hidden" name="token" value="<?=e($proposal['token'])?>"><label><input name="confirm" type="checkbox" required> Betrag, Empfänger, Text und Zahlungsziel geprüft. Nur archivieren, nicht senden.</label><button>Zahlungserinnerung bestätigen</button></form><?php endif?>
<?php if($i['status']==='issued'&&$state['outstanding_cents']>0):?><form method="post"><?php gszFields('preview');?><label>Erinnerungsdatum<input name="issued_on" type="date" required value="<?=e(date('Y-m-d'))?>"></label><label>Neues Zahlungsziel<input name="due_on" type="date" required value="<?=e((new DateTimeImmutable('+14 days'))->format('Y-m-d'))?>"></label><label>Sachlicher Erinnerungstext<textarea name="body" maxlength="5000" required>Zu der genannten Rechnung ist nach unseren erfassten Zahlungen noch ein Betrag offen. Bitte prüfen Sie den Zahlungsstand und gleichen Sie den offenen Betrag bis zum angegebenen Zahlungsziel aus. Falls Sie bereits gezahlt haben, teilen Sie uns bitte die Zahlungsdaten mit.</textarea></label><button>Erinnerung als Vorschau prüfen</button></form><?php endif?>
<h3>Bestätigte Historie</h3><?php foreach($history as $h):?><p>Stufe <?=(int)$h['stage']?> · <?=e($h['issued_on'])?> · <?=e(financeDecimal((int)$h['outstanding_cents']))?> EUR · <a href="reminder_download.php?id=<?=(int)$h['id']?>">Archiviertes PDF</a> · Versand nicht durch diese Funktion erfolgt</p><?php endforeach?></section><?php endif?><?php gszPageEnd();?>
